+                name.getValue().strip(),
+                email.getValue().strip(),
+                phone.getValue().strip(),
+                message.getValue().strip(),
+                LocalDateTime.now()));
+        grid.setItems(store.all());
+        Notification.show("Message sent");
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        // Clearing the fields has just fired value change events, so disable Send only after that
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        name.setInvalid(false);
+        email.setInvalid(false);
+        phone.setInvalid(false);
+        message.setInvalid(false);
+
+        var valid = true;
+        if (name.getValue().isBlank()) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        var emailValue = email.getValue().strip();
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            email.setErrorMessage("Enter a valid e-mail address");
+            email.setInvalid(true);
+            valid = false;
+        } else if (emailValue.isEmpty() && phone.getValue().isBlank()) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        var messageValue = message.getValue().strip();
+        if (messageValue.isEmpty()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        } else if (messageValue.codePointCount(0, messageValue.length()) > MAX_MESSAGE_LENGTH) {
+            message.setErrorMessage("Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+        return valid;
+    }
+
+}
