+package com.example.contact;
+
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps every message sent so far, newest first. It lives as long as the application,
+ * so the list is still there when a user comes back to the contact view.
+ */
+@Service
+public class MessageStore {
+
+    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public List<ContactMessage> all() {
+        return List.copyOf(messages);
+    }
+
+}
