+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private MessageStore store;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void emptySendShowsErrorsInTheBrowser() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Give an e-mail address or a phone number");
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+        assertFalse(NotificationElement.getByText(page, "Message sent").isOpen());
+    }
+
+    @Test
+    void sendingListsTheMessageAndDisablesSendUntilNextEdit() {
+        int before = store.all().size();
+        TextFieldElement.getByLabel(page, "Name").setValue("Browser Jane");
+        EmailFieldElement.getByLabel(page, "Email").setValue("jane@example.com");
+        TextAreaElement.getByLabel(page, "Message").setValue("Sent from a browser");
+
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertEquals("", TextFieldElement.getByLabel(page, "Name").getValue());
+        assertEquals(before + 1, store.all().size());
+        assertEquals("Browser Jane", store.all().getFirst().name());
+        assertFalse(send.isEnabled());
+
+        TextFieldElement.getByLabel(page, "Name").setValue("Again");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void enterKeySendsTheForm() {
+        int before = store.all().size();
+        TextFieldElement.getByLabel(page, "Name").setValue("Enter Jane");
+        TextFieldElement.getByLabel(page, "Phone").setValue("+358 40 123 4567");
+        TextAreaElement.getByLabel(page, "Message").setValue("Sent with Enter");
+
+        TextFieldElement.getByLabel(page, "Name").getFocusLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertEquals(before + 1, store.all().size());
+    }
+
+    @Test
+    void leavingWithInputAsksAndDiscardGoesToAbout() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Half Written");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        DialogElement dialog = DialogElement.getByHeaderText(page, "Discard your message?");
+        dialog.assertOpen();
+        assertTrue(page.url().endsWith("/contact"));
+
+        ButtonElement.getByText(page, "Keep editing").click();
+        dialog.assertClosed();
+        assertEquals("Half Written", TextFieldElement.getByLabel(page, "Name").getValue());
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        ButtonElement.getByText(page, "Discard").click();
+
+        page.waitForURL("**/about");
+        assertTrue(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About")).isVisible());
+    }
+
+    @Test
+    void leavingEmptyFormIsNotInterruptedAndDoesNotReloadThePage() {
+        page.evaluate("window.marker = 'still here'");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        page.waitForURL("**/about");
+        assertEquals("still here", page.evaluate("window.marker"));
+        assertFalse(DialogElement.getByHeaderText(page, "Discard your message?").isOpen());
+    }
+
+    @Test
+    void invalidEmailIsNotFlaggedByTheBrowserBeforeSend() {
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        email.setValue("not-an-email");
+        TextFieldElement.getByLabel(page, "Phone").getFocusLocator().click();
+
+        email.assertValid();
+
+        TextFieldElement.getByLabel(page, "Name").setValue("Jane");
+        TextAreaElement.getByLabel(page, "Message").setValue("Hi");
+        ButtonElement.getByText(page, "Send").click();
+
+        email.assertInvalid();
+        email.assertErrorMessage("Enter a valid e-mail address");
+    }
+
+    @Test
+    void shiftEnterInTheMessageAddsALineInsteadOfSending() {
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        message.setValue("line one");
+        message.getFocusLocator().press("Shift+Enter");
+        page.keyboard().type("line two");
+
+        assertEquals("line one\nline two", message.getValue());
+        assertFalse(NotificationElement.getByText(page, "Message sent").isOpen());
+    }
+
+    @Test
+    void enterInTheMessageAreaSends() {
+        int before = store.all().size();
+        TextFieldElement.getByLabel(page, "Name").setValue("Area Jane");
+        EmailFieldElement.getByLabel(page, "Email").setValue("area@example.com");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        message.setValue("Sent from the message area");
+
+        message.getFocusLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertEquals(before + 1, store.all().size());
+        assertEquals("Sent from the message area", store.all().getFirst().message());
+    }
+
+    @Test
+    void enterWhileTheDiscardDialogIsOpenDoesNotSend() {
+        int before = store.all().size();
+        TextFieldElement.getByLabel(page, "Name").setValue("Dialog Jane");
+        TextAreaElement.getByLabel(page, "Message").setValue("Not yet sent");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        DialogElement.getByHeaderText(page, "Discard your message?").assertOpen();
+        page.keyboard().press("Enter");
+
+        assertEquals(before, store.all().size());
+        assertFalse(NotificationElement.getByText(page, "Message sent").isOpen());
+        assertEquals("Dialog Jane", TextFieldElement.getByLabel(page, "Name").getValue());
+    }
+
+}
