+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.about.AboutView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.NotificationTester;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextAreaTester;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldTester;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void showsHeadingFormAndEnabledSendOnUntouchedForm() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void aboutLinkNavigatesToAboutView() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyFormMarksEveryRequiredFieldAndSendsNothing() {
+        navigate(ContactView.class);
+        int before = grid().getGenericDataView().getItems().toList().size();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertTrue($(Notification.class).all().isEmpty());
+        assertEquals(before, grid().getGenericDataView().getItems().toList().size());
+        assertEquals("", name().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void blankNameIsRejectedAndTypedValuesStay() {
+        navigate(ContactView.class);
+        setText(phone(), "+358 40 123 4567");
+        setText(message(), "Hello");
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertFalse(email().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals("+358 40 123 4567", phone().getValue());
+        assertEquals("Hello", message().getValue());
+    }
+
+    @Test
+    void malformedEmailIsRejectedButValidEmailOrPhoneAloneIsEnough() {
+        navigate(ContactView.class);
+        setText(name(), "Jane");
+        setText(email(), "jane@example");
+        setText(message(), "Hi");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertTrue($(Notification.class).all().isEmpty());
+
+        setText(email(), "");
+        setText(phone(), "+358 40 123 4567");
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals(1, $(Notification.class).all().size());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejectedAndExactly500IsAccepted() {
+        navigate(ContactView.class);
+        setText(name(), "Jane");
+        setText(email(), "jane@example.com");
+        setText(message(), "x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+
+        setText(message(), "x".repeat(500));
+        test(send()).click();
+
+        assertFalse(message().isInvalid());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void sendingShowsNotificationListsMessageClearsFormAndDisablesSend() {
+        navigate(ContactView.class);
+        int before = grid().getGenericDataView().getItems().toList().size();
+        setText(name(), "Jane Doe");
+        setText(email(), "jane@example.com");
+        setText(phone(), "+358 40 123 4567");
+        setText(message(), "Please call me back");
+
+        test(send()).click();
+
+        NotificationTester<Notification> notification = test($(Notification.class).single());
+        assertTrue(notification.getText().contains("Message sent"));
+        assertEquals(before + 1, grid().getGenericDataView().getItems().toList().size());
+        ContactMessage first = grid().getGenericDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Jane Doe", first.name());
+        assertEquals("Please call me back", first.message());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+
+        setText(message(), "Another message");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterSendsTheForm() {
+        navigate(ContactView.class);
+        setText(name(), "Jane");
+        setText(email(), "jane@example.com");
+        setText(message(), "Via Enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, $(Notification.class).all().size());
+        assertEquals("Via Enter", grid().getGenericDataView().getItems().findFirst().orElseThrow().message());
+    }
+
+    @Test
+    void messagesStayListedWhenComingBackToTheView() {
+        navigate(ContactView.class);
+        setText(name(), "Returning Visitor");
+        setText(email(), "visitor@example.com");
+        setText(message(), "Remember me");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals("Returning Visitor", grid().getGenericDataView().getItems().findFirst().orElseThrow().name());
+    }
+
+    @Test
+    void leavingWithTypedInputAsksFirstAndKeepEditingStays() {
+        navigate(ContactView.class);
+        setText(name(), "Half Written");
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse(dialog.isOpened());
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("Half Written", name().getValue());
+    }
+
+    @Test
+    void discardLeavesTheViewAndTheFormIsNotRestored() {
+        navigate(ContactView.class);
+        setText(message(), "Will be thrown away");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+
+    @Test
+    void leavingAnEmptyFormIsNotInterrupted() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertTrue($(Dialog.class).all().isEmpty());
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return (Grid<ContactMessage>) $(Grid.class).single();
+    }
+
+    private void setText(TextField field, String value) {
+        TextFieldTester<TextField, String> tester = test(field);
+        tester.setValue(value);
+    }
+
+    private void setText(EmailField field, String value) {
+        TextFieldTester<EmailField, String> tester = test(field);
+        tester.setValue(value);
+    }
+
+    private void setText(TextArea field, String value) {
+        TextAreaTester<TextArea> tester = test(field);
+        tester.setValue(value);
+    }
+
+}
